import * as React from 'react';
import moment from 'moment';
import { ColumnDef } from '@tanstack/react-table';
import GlobalCommanTable from '@hochhuth-consulting/hhhh-shared-ui/HHHH-UI/tables/GroupByReactTableComponents/GlobalCommanTable';
import * as globalCommon from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/globalCommon';
import { loadRootDashboardConfig } from '../../OotbOmt/loadRootDashboardConfig';
import PageSkeleton from '../../../common/PageSkeleton';
import type { IDashboardProps } from './IDashboardProps';

export default function DashboardComponent({ props }: IDashboardProps): React.ReactElement {
  const [rows, setRows] = React.useState<any[]>([]);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    void loadData();
  }, []);

  const loadData = async () => {
    try {
      const siteUrl =
        props?.Context?.pageContext?.web?.absoluteUrl ||
        props?.siteUrl ||
        '';
      const userId: number = props?.Context?.pageContext?.legacyPageContext?.userId;

      const rootCfg = await loadRootDashboardConfig({
        siteUrl,
        smartMetadataListId: props?.SmartMetadataListID,
      });

      const sites: any[] = rootCfg?.rootSiteData || [];
      const taskFetchStart = moment().subtract(90, 'days').startOf('day').toISOString();
      const filter = `(Modified ge '${taskFetchStart}') and (PercentComplete le 0.90)`;

      const siteResults = await Promise.all(
        sites.map((site: any) =>
          globalCommon.loadAllSiteTaskData(site, filter).catch(() => [] as any[])
        )
      );

      const allTasks: any[] = ([] as any[]).concat(...siteResults);
      const today = moment().format('DD/MM/YYYY');

      const todayTasks = allTasks.filter((item: any) => {
        try {
          const workingAction: any[] = Array.isArray(item.WorkingAction)
            ? item.WorkingAction
            : (globalCommon.parseJSON(item.WorkingAction) || []);
          const workingDetails = workingAction.find((wa: any) => wa.Title === 'WorkingDetails');
          return (
            workingDetails?.InformationData?.some((info: any) =>
              info.WorkingDate === today &&
              Array.isArray(info.WorkingMember) &&
              info.WorkingMember.some((member: any) => member.Id == userId)
            ) ?? false
          );
        } catch {
          return false;
        }
      });

      const enriched = todayTasks.map((item: any) => {
        const workingAction: any[] = Array.isArray(item.WorkingAction)
          ? item.WorkingAction
          : (globalCommon.parseJSON(item.WorkingAction) || []);
        const workingDetails = workingAction.find((wa: any) => wa.Title === 'WorkingDetails');
        const todayInfo = workingDetails?.InformationData?.find(
          (info: any) => info.WorkingDate === today
        );
        const team: string =
          todayInfo?.WorkingMember?.map((m: any) => m.Title)
            .filter(Boolean)
            .join(', ') ?? '';

        // PercentComplete is already 0-100 after processTask in globalCommon
        const rawPc = Number(item.PercentComplete ?? 0);
        const pc = rawPc > 1 ? rawPc : rawPc * 100;
        const status =
          pc >= 90 ? 'Completed' : pc > 0 ? 'In Progress' : 'Not Started';

        return {
          ...item,
          _status: status,
          _team: team,
          _createdBy: `${moment(item.Created).format('DD/MM/YYYY')} — ${item.Author?.Title || ''}`,
          _modifiedBy: `${moment(item.Modified).format('DD/MM/YYYY')} — ${item.Editor?.Title || ''}`,
        };
      });

      setRows(enriched);
    } catch (e) {
      console.error('[Dashboard] loadData failed', e);
    } finally {
      setLoading(false);
    }
  };

  const columns = React.useMemo<ColumnDef<any, unknown>[]>(
    () => [
      {
        accessorFn: (row) => row?.Title,
        id: 'Title',
        placeholder: 'Title',
        header: '',
        size: 280,
        resetColumnFilters: false,
        resetSorting: false,
        cell: ({ getValue }) => (
          <span className="font-semibold text-[13px]" style={{ color: 'var(--SiteColor, #2F5596)' }}>
            {String(getValue() ?? '')}
          </span>
        ),
      },
      {
        accessorFn: (row) => row?._status,
        id: 'Status',
        placeholder: 'Status',
        header: '',
        size: 110,
        resetColumnFilters: false,
        resetSorting: false,
        cell: ({ getValue }) => <span>{String(getValue() ?? '')}</span>,
      },
      {
        accessorFn: (row) => row?.ProjectTitle,
        id: 'Project',
        placeholder: 'Project',
        header: '',
        size: 200,
        resetColumnFilters: false,
        resetSorting: false,
        cell: ({ getValue }) => <span>{String(getValue() ?? '')}</span>,
      },
      {
        accessorFn: (row) => row?.PortfolioTitle,
        id: 'Portfolio',
        placeholder: 'Portfolio',
        header: '',
        size: 200,
        resetColumnFilters: false,
        resetSorting: false,
        cell: ({ getValue }) => <span>{String(getValue() ?? '')}</span>,
      },
      {
        accessorFn: (row) => row?._team,
        id: 'Team',
        placeholder: 'Team',
        header: '',
        size: 180,
        resetColumnFilters: false,
        resetSorting: false,
        cell: ({ getValue }) => <span>{String(getValue() ?? '')}</span>,
      },
      {
        accessorFn: (row) => row?.Categories,
        id: 'Category',
        placeholder: 'Category',
        header: '',
        size: 120,
        resetColumnFilters: false,
        resetSorting: false,
        cell: ({ getValue }) => <span>{String(getValue() ?? '')}</span>,
      },
      {
        accessorFn: (row) => row?._createdBy,
        id: 'CreatedBy',
        placeholder: 'Created By',
        header: '',
        size: 190,
        resetColumnFilters: false,
        resetSorting: false,
        cell: ({ getValue }) => (
          <span className="text-xs text-slate-600">{String(getValue() ?? '')}</span>
        ),
      },
      {
        accessorFn: (row) => row?._modifiedBy,
        id: 'ModifiedBy',
        placeholder: 'Modified By',
        header: '',
        size: 190,
        resetColumnFilters: false,
        resetSorting: false,
        cell: ({ getValue }) => (
          <span className="text-xs text-slate-600">{String(getValue() ?? '')}</span>
        ),
      },
    ],
    []
  );

  if (loading) {
    return <PageSkeleton variant="default" />;
  }

  return (
    <div className="w-full min-w-0 bg-white flex flex-col px-4 pt-3 pb-6 min-h-screen">
      <div className="sticky top-0 z-40 bg-white pb-2">
        <h2
          className="text-xl font-bold mb-3"
          style={{ color: 'var(--SiteColor, #2f5596)' }}
        >
          {"Today's Working Tasks"}
        </h2>
      </div>
      {rows.length === 0 ? (
        <div className="text-sm text-slate-500 mt-8 text-center">
          No tasks assigned to you for today.
        </div>
      ) : (
        <GlobalCommanTable
          columns={columns}
          data={rows}
          paginatedTable={false}
          pageName="Dashboard"
          showHeader={true}
          showRestructureButton={false}
          showCreationAllButton={false}
        />
      )}
    </div>
  );
}

